-- mod-hearthstone: the pages of the gossip tutorials.
--
-- Seven replies per tutorial (the answer to each option, the last one to the final option). Each is a
-- broadcast_text row and an npc_text row with the same id: HsIntroGlue.cpp sends the npc_text id with the gossip menu.
--   9195111 to 9195117: the lesson of Ezra and Ibelin
--   9195101 to 9195107: Byron's trade
-- All rows are rebuilt each run. No backslashes, no semicolons in strings.

DELETE FROM `npc_text` WHERE `ID` IN (9195111, 9195112, 9195113, 9195114, 9195115, 9195116, 9195117, 9195101, 9195102, 9195103, 9195104, 9195105, 9195106, 9195107);
DELETE FROM `broadcast_text` WHERE `entry` IN (9195111, 9195112, 9195113, 9195114, 9195115, 9195116, 9195117, 9195101, 9195102, 9195103, 9195104, 9195105, 9195106, 9195107);

INSERT INTO `broadcast_text`
  (`entry`, `male_text`, `female_text`, `chat_type`, `sound_id`, `language_id`, `emote_id1`, `emote_id2`, `emote_id3`,
   `emote_delay1`, `emote_delay2`, `emote_delay3`)
VALUES
  (9195111, "Let's start with the important part.$B$BBoth players have a Hero with 30 Health and a deck of 30 cards.$B$BYour goal is simple: bring the enemy Hero down to 0 Health before they do the same to you.$B$BAt the beginning of the game, one player draws 3 cards.$B$BThe player going second draws 4 cards and also receives The Coin, a special card that gives you one extra Mana for a turn.$B$BBefore the game starts, you may replace any of the cards in your starting hand once.$B$BDon't like what you drew? Send it back and hope for something better.", "Let's start with the important part.$B$BBoth players have a Hero with 30 Health and a deck of 30 cards.$B$BYour goal is simple: bring the enemy Hero down to 0 Health before they do the same to you.$B$BAt the beginning of the game, one player draws 3 cards.$B$BThe player going second draws 4 cards and also receives The Coin, a special card that gives you one extra Mana for a turn.$B$BBefore the game starts, you may replace any of the cards in your starting hand once.$B$BDon't like what you drew? Send it back and hope for something better.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195112, "At the beginning of each of your turns, you draw one card.$B$BYou start the game with 1 Mana Crystal, and gain another each turn until you reach a maximum of 10.$B$BYour Mana Crystals refill completely at the start of every turn.$B$BMana is what you spend to play cards and use your Hero Power.$B$BSo if a card costs 4 Mana and you only have 3...$B$BWell, the card isn't going anywhere.", "At the beginning of each of your turns, you draw one card.$B$BYou start the game with 1 Mana Crystal, and gain another each turn until you reach a maximum of 10.$B$BYour Mana Crystals refill completely at the start of every turn.$B$BMana is what you spend to play cards and use your Hero Power.$B$BSo if a card costs 4 Mana and you only have 3...$B$BWell, the card isn't going anywhere.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195113, "Minions are creatures you summon onto the board.$B$BEach one has Attack and Health, and it stays in play until something destroys it.$B$BMost minions cannot attack on the same turn they're played.$B$BA minion with Charge can.$B$BNormally, each minion may attack once per turn. A minion with Windfury may attack twice.$B$BWhen one minion attacks another, they deal their Attack damage to each other at the same time.$B$BSo choose your fights carefully.", "Minions are creatures you summon onto the board.$B$BEach one has Attack and Health, and it stays in play until something destroys it.$B$BMost minions cannot attack on the same turn they're played.$B$BA minion with Charge can.$B$BNormally, each minion may attack once per turn. A minion with Windfury may attack twice.$B$BWhen one minion attacks another, they deal their Attack damage to each other at the same time.$B$BSo choose your fights carefully.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195114, "They can.$B$BUnless something is standing in the way.$B$BA minion with Taunt must be attacked before you can attack other characters past it.$B$BA minion with Divine Shield ignores the first damage it would take. Then the shield disappears.$B$BSome minions also have effects when they're played or destroyed.$B$BBattlecry happens immediately when you play the minion from your hand.$B$BDeathrattle happens when the minion dies.", "They can.$B$BUnless something is standing in the way.$B$BA minion with Taunt must be attacked before you can attack other characters past it.$B$BA minion with Divine Shield ignores the first damage it would take. Then the shield disappears.$B$BSome minions also have effects when they're played or destroyed.$B$BBattlecry happens immediately when you play the minion from your hand.$B$BDeathrattle happens when the minion dies.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195115, "Spells do whatever is written on the card, then they're gone.$B$BSimple enough.$B$BSecrets are different. They stay hidden until something happens that causes them to trigger.$B$BYour opponent knows you've played a Secret.$B$BThey just don't know what it is.$B$BWeapons allow your Hero to attack.$B$BEach time your Hero attacks with a weapon, it loses 1 Durability. When the Durability reaches zero, the weapon is destroyed.$B$BAnd every Hero has a unique Hero Power.$B$BThey can be used once per turn.", "Spells do whatever is written on the card, then they're gone.$B$BSimple enough.$B$BSecrets are different. They stay hidden until something happens that causes them to trigger.$B$BYour opponent knows you've played a Secret.$B$BThey just don't know what it is.$B$BWeapons allow your Hero to attack.$B$BEach time your Hero attacks with a weapon, it loses 1 Durability. When the Durability reaches zero, the weapon is destroyed.$B$BAnd every Hero has a unique Hero Power.$B$BThey can be used once per turn.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195116, "A few things.$B$BYou can have no more than 7 minions on your side of the board.$B$BYour hand can hold no more than 10 cards.$B$BIf you draw a card while your hand is full, that card is destroyed.$B$BSo keep an eye on how many cards you're holding.$B$BAnd eventually, you may run out of cards in your deck.$B$BWhen that happens, trying to draw another card causes Fatigue damage instead.$B$BThe first failed draw hurts a little.$B$BThe next hurts more.$B$BThen more again.$B$BYou don't want to find out how high it can go.$B$BWhen you've played your cards, made your attacks, and done everything you want to do, you end your turn.$B$BThen it's your opponent's turn.", "A few things.$B$BYou can have no more than 7 minions on your side of the board.$B$BYour hand can hold no more than 10 cards.$B$BIf you draw a card while your hand is full, that card is destroyed.$B$BSo keep an eye on how many cards you're holding.$B$BAnd eventually, you may run out of cards in your deck.$B$BWhen that happens, trying to draw another card causes Fatigue damage instead.$B$BThe first failed draw hurts a little.$B$BThe next hurts more.$B$BThen more again.$B$BYou don't want to find out how high it can go.$B$BWhen you've played your cards, made your attacks, and done everything you want to do, you end your turn.$B$BThen it's your opponent's turn.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195117, "Good.$B$BDon't worry about remembering every little thing immediately, $N.$B$BYou'll learn most of it just by playing.$B$BWatch your Mana, read your cards, and think before you attack.$B$BThe rest comes with time.$B$BNow you're ready. If you want, I can help you find opponents, there is always somebody around.", "Good.$B$BDon't worry about remembering every little thing immediately, $N.$B$BYou'll learn most of it just by playing.$B$BWatch your Mana, read your cards, and think before you attack.$B$BThe rest comes with time.$B$BNow you're ready. If you want, I can help you find opponents, there is always somebody around.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195101, "Mostly?$B$BI help you turn bad luck into something useful.$B$BYou open enough packs, you're going to end up with cards you don't need. At the same time, there's always going to be some card you want that refuses to show up.$B$BI help with both.", "Mostly?$B$BI help you turn bad luck into something useful.$B$BYou open enough packs, you're going to end up with cards you don't need. At the same time, there's always going to be some card you want that refuses to show up.$B$BI help with both.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195102, "Bring them to me.$B$BI can break them down into Arcane Dust.$B$BThe Committee wants a Card Master handling it, so that's my job.$B$BHonestly, it's better this way. I've seen what adventurers do when they're told to dispose of something themselves.", "Bring them to me.$B$BI can break them down into Arcane Dust.$B$BThe Committee wants a Card Master handling it, so that's my job.$B$BHonestly, it's better this way. I've seen what adventurers do when they're told to dispose of something themselves.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195103, "Dust is the useful part.$B$BYou give up a card you don't need, you get some dust back.$B$BKeep doing that and eventually you've got enough to get something you actually want.$B$BThink of it like trading a bunch of bad draws for one good one.$B$BNot a bad deal.", "Dust is the useful part.$B$BYou give up a card you don't need, you get some dust back.$B$BKeep doing that and eventually you've got enough to get something you actually want.$B$BThink of it like trading a bunch of bad draws for one good one.$B$BNot a bad deal.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195104, "Yeah.$B$BThat's the good part.$B$BIf you know exactly what you're looking for and you've got enough dust, I can help you get that card directly.", "Yeah.$B$BThat's the good part.$B$BIf you know exactly what you're looking for and you've got enough dust, I can help you get that card directly.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195105, "I didn't really expect to care that much about Hearthstone.$B$BThen I started playing.$B$B'I didn't think I'd like the game. Within an hour I was hooked.'$B$BAfter that?$B$BWell... here we are.$B$BNow people come find me in caves and city squares because they desperately need one more card for their deck.$B$BCould be worse.", "I didn't really expect to care that much about Hearthstone.$B$BThen I started playing.$B$B'I didn't think I'd like the game. Within an hour I was hooked.'$B$BAfter that?$B$BWell... here we are.$B$BNow people come find me in caves and city squares because they desperately need one more card for their deck.$B$BCould be worse.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195106, "Yeah.$B$BDon't rush to get rid of everything that looks bad.$B$BTry stuff.$B$BBuild weird decks. Lose some games. Figure out why you lost them.$B$BSometimes the card you thought was useless ends up being the one that makes the whole thing work.$B$BAnd if the game goes completely wrong?$B$BTurtle all day.$B$BYou'll figure it out.$B$BJust come back every once in a while, alright?$B$BDon't make me wait until we're old.", "Yeah.$B$BDon't rush to get rid of everything that looks bad.$B$BTry stuff.$B$BBuild weird decks. Lose some games. Figure out why you lost them.$B$BSometimes the card you thought was useless ends up being the one that makes the whole thing work.$B$BAnd if the game goes completely wrong?$B$BTurtle all day.$B$BYou'll figure it out.$B$BJust come back every once in a while, alright?$B$BDon't make me wait until we're old.", 0, 0, 0, 0, 0, 0, 0, 0, 0),
  (9195107, "Good.$B$BI'll be here.", "Good.$B$BI'll be here.", 0, 0, 0, 0, 0, 0, 0, 0, 0);

